Current Date: April 4 2025
Title: Is hooks available in 1.7.x?
Description: I define a model like this:

module.exports = function(sequelize, DataTypes) {
    return sequelize.define('test', {
        id: {
            type: DataTypes.INTEGER,
            primaryKey: true,
            autoIncrement: true
        },
        name: {
            type: DataTypes.STRING
        },
        _json_field: {
            type: DataTypes.TEXT
        }
    }, {
        hooks: {
            afterFind: function(ins) {
                console.log('afterFind called');
                this.setDataValue('json_field', this.getDataValue('_json_field').toJSON());
            },
            beforeUpdate: function(ins) {
                console.log('beforeUpdate called');
                this.setDataValue('_json_field', json.stringify(this.getDataValue('json_field')));
            }
        }
    });
};
But the hooks have no effect.Is hooks available in 1.7.x?


